    | FStarC_Parser_TokenKind.STRING -> true
    | FStarC_Parser_TokenKind.TRUE -> true
    | FStarC_Parser_TokenKind.FALSE -> true
    | FStarC_Parser_TokenKind.REAL -> true
    | FStarC_Parser_TokenKind.REIFY -> true
    | FStarC_Parser_TokenKind.RANGE_OF -> true
    | FStarC_Parser_TokenKind.SET_RANGE_OF -> true
    | FStarC_Parser_TokenKind.UINT8 -> true
    | FStarC_Parser_TokenKind.INT8 -> true
    | FStarC_Parser_TokenKind.UINT16 -> true
    | FStarC_Parser_TokenKind.INT16 -> true
    | FStarC_Parser_TokenKind.UINT32 -> true
    | FStarC_Parser_TokenKind.INT32 -> true
    | FStarC_Parser_TokenKind.UINT64 -> true
    | FStarC_Parser_TokenKind.INT64 -> true
    | FStarC_Parser_TokenKind.SIZET -> true
    | tmp -> false
  )

let is_genBinder_start_kind (k : FStarC_Parser_TokenKind.token_kind) : bool =
  (match k with
    | FStarC_Parser_TokenKind.LBRACE_BAR -> true
    | FStarC_Parser_TokenKind.LPAREN -> true
    | FStarC_Parser_TokenKind.DOT_DOT -> true
    | FStarC_Parser_TokenKind.LBRACK -> true
    | FStarC_Parser_TokenKind.LBRACE -> true
    | FStarC_Parser_TokenKind.LENS_PAREN_LEFT -> true
    | FStarC_Parser_TokenKind.MINUS -> true
    | FStarC_Parser_TokenKind.BACKTICK_PERC -> true
    | FStarC_Parser_TokenKind.HASH -> true
    | FStarC_Parser_TokenKind.DOLLAR -> true
    | FStarC_Parser_TokenKind.LBRACK_AT_AT_AT -> true
    | FStarC_Parser_TokenKind.IDENT -> true
    | FStarC_Parser_TokenKind.UNDERSCORE -> true
    | FStarC_Parser_TokenKind.NAME -> true
    | tmp -> (is_constant_kind k)
  )

let is_atomic_pattern_start_kind (k : FStarC_Parser_TokenKind.token_kind) : bool =
  (((<>) k FStarC_Parser_TokenKind.LBRACE_BAR) && (is_genBinder_start_kind k))

let syntax_error (r : FStarC_Range_Type.range) (msg : string) : 'a =
  (FStarC_Errors.raise_error_text r FStarC_Errors_Codes.Fatal_SyntaxError msg)

let rec pat_names (bs : (FStarC_Parser_AST.pattern) list) : (FStarC_Ident.ident) list =
