          (x :: tmp2))
        | tmp -> (let tmp1 = (FStarC_Parser_AST.pat_to_string b) in
          let tmp2 = (Prims.strcat "Inline constraints require simple variable binders, got: " tmp1) in
          (syntax_error (b).FStarC_Parser_AST.prange tmp2))
      )
  )

let rec find_machine_int (k : FStarC_Parser_TokenKind.token_kind) (l : ((FStarC_Parser_TokenKind.token_kind * FStarC_Const.signedness * FStarC_Const.width)) list) : ((FStarC_Const.signedness * FStarC_Const.width)) option =
  (match l with
    | [] -> None
    | ((k', s, w) :: l1) -> (if ((=) k k') then (Some ((s, w))) else (find_machine_int k l1))
  )

let machine_int_kinds : ((FStarC_Parser_TokenKind.token_kind * FStarC_Const.signedness * FStarC_Const.width)) list =
  ((FStarC_Parser_TokenKind.UINT8, FStarC_Const.Unsigned, FStarC_Const.Int8) :: ((FStarC_Parser_TokenKind.INT8, FStarC_Const.Signed, FStarC_Const.Int8) :: ((FStarC_Parser_TokenKind.UINT16, FStarC_Const.Unsigned, FStarC_Const.Int16) :: ((FStarC_Parser_TokenKind.INT16, FStarC_Const.Signed, FStarC_Const.Int16) :: ((FStarC_Parser_TokenKind.UINT32, FStarC_Const.Unsigned, FStarC_Const.Int32) :: ((FStarC_Parser_TokenKind.INT32, FStarC_Const.Signed, FStarC_Const.Int32) :: ((FStarC_Parser_TokenKind.UINT64, FStarC_Const.Unsigned, FStarC_Const.Int64) :: ((FStarC_Parser_TokenKind.INT64, FStarC_Const.Signed, FStarC_Const.Int64) :: ((FStarC_Parser_TokenKind.SIZET, FStarC_Const.Unsigned, FStarC_Const.Sizet) :: [])))))))))

let constant (ps : FStarC_Parser_Pratt.pstate) : FStarC_Const.sconst =
  (let t = (FStarC_Parser_Pratt.peek ps) in
  (if (not (is_constant_kind (t).FStarC_Parser_Lexer.kind)) then (FStarC_Parser_Pratt.fail ps) else ((ignore (FStarC_Parser_Pratt.advance ps));
  (match (t).FStarC_Parser_Lexer.kind with
    | FStarC_Parser_TokenKind.LPAREN_RPAREN -> FStarC_Const.Const_unit
    | FStarC_Parser_TokenKind.INT -> (let tmp = (FStarC_Const.parse_int_literal (t).FStarC_Parser_Lexer.text) in
      (match tmp with
        | (v, b) -> (FStarC_Const.Const_int (v, b))
      ))
    | FStarC_Parser_TokenKind.CHAR -> (match (t).FStarC_Parser_Lexer.extra with
        | (FStarC_Parser_Lexer.CharLit (c)) -> (FStarC_Const.Const_char ((Z.to_int c)))
        | tmp -> (FStarC_Effect.failwith "impossible: CHAR without payload")
      )
    | FStarC_Parser_TokenKind.STRING -> (FStarC_Const.Const_string ((t).FStarC_Parser_Lexer.text, (FStarC_Parser_Pratt.tok_rng ps t)))
    | FStarC_Parser_TokenKind.TRUE -> (FStarC_Const.Const_bool (true))
    | FStarC_Parser_TokenKind.FALSE -> (FStarC_Const.Const_bool (false))
    | FStarC_Parser_TokenKind.REAL -> (match (FStarC_Real.of_string (t).FStarC_Parser_Lexer.text) with
        | (Some (r)) -> (FStarC_Const.Const_real (r))
        | None -> (FStarC_Effect.failwith (Prims.strcat "Invalid real literal: " (t).FStarC_Parser_Lexer.text))
      )
    | FStarC_Parser_TokenKind.REIFY -> (FStarC_Const.Const_reify (None))
    | FStarC_Parser_TokenKind.RANGE_OF -> FStarC_Const.Const_range_of
    | FStarC_Parser_TokenKind.SET_RANGE_OF -> FStarC_Const.Const_set_range_of
    | k -> (match (find_machine_int k machine_int_kinds) with
        | (Some ((s, w))) -> (let tmp = (FStarC_Const.parse_int_literal (t).FStarC_Parser_Lexer.text) in
          (match tmp with
            | (v, b) -> (FStarC_Const.Const_machine_int (v, b, s, w))
          ))
        | None -> (FStarC_Effect.failwith "impossible")
      )
  ))))

let is_multiBinder_start_kind (k : FStarC_Parser_TokenKind.token_kind) : bool =
