  (match res with
    | (FStar_Pervasives.Inl (None)) -> ((BatList.rev acc), None)
    | (FStar_Pervasives.Inl ((Some (ds)))) -> (parse_incremental_gen__go g ps p_one next_ok (FStar_List_Tot_Base.rev_acc ds acc))
    | (FStar_Pervasives.Inr (err)) -> ((BatList.rev acc), (Some (err)))
  ))

let parse_incremental_gen (g : FStarC_Parser_Pratt.grammar) (ps : FStarC_Parser_Pratt.pstate) (p_one : (FStarC_Parser_Pratt.pstate -> ('a) list)) (next_ok : (FStarC_Parser_TokenKind.token_kind -> bool)) : (('a) list * ((FStarC_Errors_Codes.error_code * (PPrint.document) list * FStarC_Range_Type.range)) option) =
  (parse_incremental_gen__go g ps p_one next_ok [])

let rec drop (n : Prims.int) (l : ('a) list) : ('a) list =
  (if (Prims.op_Less_Equals n Prims.int_zero) then l else (match l with
    | [] -> []
    | (tmp :: l1) -> (drop (Prims.op_Minus n Prims.int_one) l1)
  ))

let parse_incremental (fname : string) (contents : string) (line : Prims.int) (col : Prims.int) : ((FStarC_Parser_AST.decl) list * ((string * FStarC_Range_Type.range)) list * ((FStarC_Errors_Codes.error_code * (PPrint.document) list * FStarC_Range_Type.range)) option) =
  (let tmp = (start fname contents line col) in
  (match tmp with
    | (ps, comments) -> (let ncomments = ((fun l -> Z.of_int (BatList.length l)) comments) in
      let tmp1 = (parse_incremental_gen fstar_grammar ps p_decl (fun k -> (FStar_List_Tot_Base.mem k start_of_next_decl_kinds))) in
      (match tmp1 with
        | (decls, err) -> (match err with
            | None -> (decls, comments, None)
            | (Some (tmp2)) -> (let tmp3 = (!((ps).FStarC_Parser_Pratt.furthest)) in
              let tmp4 = (!((ps).FStarC_Parser_Pratt.idx)) in
              let f = (FStarC_SmallInt.max tmp3 tmp4) in
              let scrut = (FStarC_Parser_Pratt.tok_at ps f) in
              let seen = (scrut).FStarC_Parser_Lexer.ncom in
              (decls, (drop (Prims.op_Minus ncomments seen) comments), err))
          )
      ))
  ))

let parse_term (fname : string) (contents : string) (line : Prims.int) (col : Prims.int) : FStarC_Parser_AST.term =
  (let tmp = (start fname contents line col) in
  (match tmp with
    | (ps, tmp1) -> (run ps (fun tmp2 -> (let t = (p_term ps) in
      (ignore (FStarC_Parser_Pratt.expect ps FStarC_Parser_TokenKind.EOF));
      t)))
  ))

